import RNA
import random

target = "((......((......))......(((......((......))......((......))......)))......))" + "....."
assert len(target) == 81

pair_pos = []
stack = []
for i, c in enumerate(target):
    if c == '(':
        stack.append(i)
    elif c == ')':
        j = stack.pop()
        pair_pos.append((j, i))

paired = set()
for a, b in pair_pos:
    paired.add(a)
    paired.add(b)
unpaired = [i for i in range(81) if i not in paired]

def fold(seq):
    fc = RNA.fold_compound(seq)
    mfe, energy = fc.mfe()
    return mfe, energy

def bpd(a, b):
    return RNA.bp_distance(a, b)

random.seed(42)

def random_pair():
    return random.choice([('G','C'), ('C','G'), ('A','U'), ('U','A'), ('G','U'), ('U','G')])

def init_seq():
    s = [None]*81
    for a, b in pair_pos:
        pa, pb = random_pair()
        s[a] = pa
        s[b] = pb
    for i in unpaired:
        s[i] = random.choice('ACGU')
    return s

def score(seq):
    s = ''.join(seq)
    mfe, e = fold(s)
    return bpd(mfe, target), mfe, e

best_overall = None
best_overall_score = 999

for restart in range(40):
    seq = init_seq()
    cur_score, cur_mfe, cur_e = score(seq)
    T = 2.0
    for step in range(3000):
        T = max(0.05, 2.0 * (0.999 ** step))
        i = random.randrange(81)
        old = seq[i]
        # find partner if paired
        partner = None
        for a,b in pair_pos:
            if a == i: partner = b
            if b == i: partner = a
        if partner is not None:
            old_partner = seq[partner]
            pa, pb = random_pair()
            seq[i] = pa
            seq[partner] = pb
        else:
            seq[i] = random.choice('ACGU')
        new_score, new_mfe, new_e = score(seq)
        if new_score <= cur_score or random.random() < __import__('math').exp((cur_score-new_score)/T):
            cur_score, cur_mfe, cur_e = new_score, new_mfe, new_e
        else:
            seq[i] = old
            if partner is not None:
                seq[partner] = old_partner
        if cur_score == 0:
            break
    if cur_score < best_overall_score:
        best_overall_score = cur_score
        best_overall = ''.join(seq)
        print(f"restart {restart}: score={cur_score} seq={best_overall}")
    if best_overall_score == 0:
        break

print("BEST:", best_overall_score, best_overall)

